      function catName(id) {
        for (var i = 0; i < CATEGORIES.length; i++) if (CATEGORIES[i].id === id) return CATEGORIES[i].name;
        return "";
      }
      function countByCat(id) {
        return ARTICLES.filter(function (a) { return a.cat === id; }).length;
      }

      /* Categories */
      var catGrid = document.getElementById("catGrid");
      if (catGrid) CATEGORIES.forEach(function (c) {
        var n = countByCat(c.id);
        var btn = document.createElement("button");
        btn.type = "button";
        btn.className = "cat-card";
        btn.innerHTML =
          '<span class="cat-name">' + c.name + "</span>" +
          '<span class="cat-desc">' + c.desc + "</span>" +
          '<span class="cat-count">記事 ' + n + " 本</span>";
        btn.addEventListener("click", function () {
          setFilter(c.id);
          var atEl = document.getElementById("articles"); if (atEl) atEl.scrollIntoView({ behavior: "smooth" });
        });
        catGrid.appendChild(btn);
      });

      /* Chips */
      var chips = document.getElementById("chips");
      var chipDefs = [{ id: "all", name: "すべて" }].concat(CATEGORIES);
      if (chips) chipDefs.forEach(function (c) {
        var b = document.createElement("button");
        b.type = "button";
        b.className = "chip";
        b.textContent = c.name;
        b.setAttribute("aria-pressed", c.id === "all" ? "true" : "false");
        b.dataset.cat = c.id;
        b.addEventListener("click", function () { setFilter(c.id); });
        chips.appendChild(b);
      });

      function setFilter(id) {
        currentFilter = id;
        var bs = chips ? chips.querySelectorAll(".chip") : [];
        bs.forEach(function (b) { b.setAttribute("aria-pressed", b.dataset.cat === id ? "true" : "false"); });
        renderPosts();
      }

      /* Post grid */
      var postGrid = document.getElementById("postGrid");
      function renderPosts() {
        if (!postGrid) return;
        postGrid.innerHTML = "";
        var list = ARTICLES.filter(function (a) { return currentFilter === "all" || a.cat === currentFilter; });
        list.forEach(function (a) {
          var card = document.createElement("button");
          card.type = "button";
          card.className = "post-card";
          card.innerHTML =
            '<img src="' + a.img + '" alt="' + a.alt + '" loading="lazy" />' +
            '<span class="post-body">' +
              '<span class="post-meta"><span class="tag">' + catName(a.cat) + "</span><span>" + a.date + "</span></span>" +
              "<h3>" + a.title + "</h3>" +
              "<p>" + a.excerpt + "</p>" +
              '<span class="read">記事を読む →</span>' +
            "</span>";
          card.addEventListener("click", function () { openArticle(a.id); });
          postGrid.appendChild(card);
        });
      }
      renderPosts();

      /* Pillars */
      var pillarGrid = document.getElementById("pillarGrid");
      if (pillarGrid) {
        PILLARS.forEach(function (p) {
          var div = document.createElement("div");
          div.className = "pillar-card";
          div.innerHTML =
            '<span class="p-num">' + p.num + "</span><h3>" + p.name + "</h3><p>" + p.desc + "</p>" +
            "<ul>" + p.points.map(function (x) { return "<li>" + x + "</li>"; }).join("") + "</ul>" +
            '<button class="pillar-link" type="button">入口の解説記事を読む →</button>' +
            (p.id === "profile" ? '<br /><button class="pillar-link" type="button" data-zukan-link>精油図鑑で1本ずつ探す →</button>' : "");
          div.querySelector(".pillar-link").addEventListener("click", function () { openArticle(p.article); });
          var zl0 = div.querySelector("[data-zukan-link]");
          if (zl0) zl0.addEventListener("click", function () { openZukan(); });
          pillarGrid.appendChild(div);
        });
      }

      /* Learn grid */
      var learnGrid = document.getElementById("learnGrid");
      function renderLearn() {
        if (!learnGrid) return;
        learnGrid.innerHTML = "";
        LEARN_ARTICLES.forEach(function (a) {
          var card = document.createElement("a");
          card.className = "post-card";
          card.href = "articles/" + a.id + ".html";
          card.innerHTML =
            '<img src="' + a.img + '" alt="' + a.alt + '" loading="lazy" />' +
            '<span class="post-body">' +
              '<span class="post-meta"><span class="tag">' + pillarName(a.pillar) + "</span><span>" + a.date + "</span></span>" +
              "<h3>" + a.title + "</h3><p>" + a.excerpt + "</p>" +
              '<span class="read">解説記事を読む →</span></span>';
          learnGrid.appendChild(card);
        });
      }
      renderLearn();

      /* Guide view */
      var guideView = document.getElementById("guideView");
      function openGuide() {
        homeView.style.display = "none";
        articleView.classList.remove("open");
        var zv = document.getElementById("zukanView");
        if (zv) zv.classList.remove("open");
        guideView.classList.add("open");
        window.scrollTo({ top: 0 });
      }
      function closeGuide() {
        guideView.classList.remove("open");
        homeView.style.display = "";
        restoreMeta();
      }
      ["openGuideBtn", "openGuideBtn2"].forEach(function (id) {
        var el = document.getElementById(id);
        if (el) el.addEventListener("click", openGuide);
      });
      var gBack = document.getElementById("guideBackBtn");
      if (gBack) gBack.addEventListener("click", function () { closeGuide(); window.scrollTo({ top: 0 }); });
      var gLearn = document.getElementById("guideToLearn");
      if (gLearn) gLearn.addEventListener("click", function () { closeGuide(); setTimeout(function () { var lt = document.getElementById("learn"); if (lt) lt.scrollIntoView(); }, 60); });

