      function isEn() { return typeof LANG !== "undefined" && LANG === "en"; }
      function oilThemeName(id) {
        for (var i = 0; i < OIL_THEMES.length; i++) if (OIL_THEMES[i].id === id) return isEn() ? OIL_THEMES[i].nameEn : OIL_THEMES[i].name;
        return "";
      }
      function oilsForArticle(articleId) {
        return OILS.filter(function (o) { return o.articles.indexOf(articleId) !== -1; });
      }

      var zukanView = document.getElementById("zukanView");
      var zukanTheme = "all";
      function renderZukan(highlightId) {
        var en = isEn();
        /* Theme chips */
        var chipsEl = document.getElementById("zukanChips");
        chipsEl.innerHTML = "";
        OIL_THEMES.forEach(function (t) {
          var b = document.createElement("button");
          b.type = "button";
          b.className = "chip";
          b.textContent = en ? t.nameEn : t.name;
          b.setAttribute("aria-pressed", zukanTheme === t.id ? "true" : "false");
          b.addEventListener("click", function () { zukanTheme = t.id; renderZukan(); });
          chipsEl.appendChild(b);
        });
        var list = OILS.filter(function (o) { return zukanTheme === "all" || o.themes.indexOf(zukanTheme) !== -1; });
        /* Gojuuon row links (rows present in the filtered list) */
        var rowsEl = document.getElementById("zukanRows");
        rowsEl.innerHTML = "";
        OIL_ROWS.forEach(function (r) {
          var has = list.some(function (o) { return o.row === r; });
          if (!has) return;
          var b = document.createElement("button");
          b.type = "button";
          b.className = "zukan-row-link";
          b.textContent = r + (en ? " row" : "行");
          b.addEventListener("click", function () {
            var head = document.getElementById("zukanRow-" + r);
            if (head) head.scrollIntoView({ behavior: "smooth", block: "start" });
          });
          rowsEl.appendChild(b);
        });
        document.getElementById("zukanCount").textContent = en
          ? ("Showing " + list.length + " of " + OILS.length + " oils")
          : ("全" + OILS.length + "種のうち " + list.length + "種を表示中");
        /* Grouped list */
        var mount = document.getElementById("zukanList");
        mount.innerHTML = "";
        OIL_ROWS.forEach(function (r) {
          var inRow = list.filter(function (o) { return o.row === r; });
          if (!inRow.length) return;
          var head = document.createElement("h2");
          head.className = "zukan-row-head";
          head.id = "zukanRow-" + r;
          head.textContent = r + (en ? " row" : "行");
          mount.appendChild(head);
          var grid = document.createElement("div");
          grid.className = "oil-grid";
          inRow.forEach(function (o) { grid.appendChild(oilCard(o, en, highlightId)); });
          mount.appendChild(grid);
        });
        if (!list.length) {
          var none = document.createElement("p");
          none.style.color = "var(--ink-soft)";
          none.textContent = en ? "No oils match this theme yet." : "このテーマに当てはまる精油はまだ登録されていません。";
          mount.appendChild(none);
        }
      }
      function oilCard(o, en, highlightId) {
        var card = document.createElement("div");
        card.className = "oil-card" + (highlightId === o.id ? " highlight" : "");
        card.id = "oil-" + o.id;
        var oe = OIL_EN[o.id] || {};
        var mainName = en ? o.en : o.name;
        var sub = en ? (o.name + "（" + o.reading + "）") : (o.reading + " ／ " + o.en);
        var tags =
          '<span class="oil-tag">' + (en ? OIL_FAMILIES[o.family].nameEn : OIL_FAMILIES[o.family].name) + "</span>" +
          (o.note ? '<span class="oil-tag">' + (en ? OIL_NOTES[o.note].nameEn : OIL_NOTES[o.note].name) + "</span>" : "") +
          o.themes.map(function (t) { return '<span class="oil-tag theme">' + oilThemeName(t) + "</span>"; }).join("");
        var metaRows = "";
        function metaRow(label, value) { return '<div><dt>' + label + "</dt><dd>" + value + "</dd></div>"; }
        if (o.latin) metaRows += metaRow(en ? "Latin name" : "学名", en && o.latinEn ? o.latinEn : o.latin);
        if (o.fam) metaRows += metaRow(en ? "Family" : "科名", en && o.famEn ? o.famEn : o.fam);
        if (o.part) metaRows += metaRow(en ? "Part" : "抽出部位", en && o.partEn ? o.partEn : o.part);
        if (o.method) metaRows += metaRow(en ? "Method" : "抽出法", en && o.methodEn ? o.methodEn : o.method);
        if (o.comp) metaRows += metaRow(en ? "Components" : "主な成分", en && o.compEn ? o.compEn : o.comp);
        var cautionText = en && oe.caution ? oe.caution : o.caution;
        var artBtns = o.articles.map(function (aid) {
          var a = findArticle(aid);
          if (!a) return "";
          return '<button type="button" data-oil-article="' + aid + '">' + (typeof locTitle === "function" ? locTitle(a) : a.title) + "</button>";
        }).join("");
        card.innerHTML =
          '<div><h3 class="oil-name"><span class="fam-dot fam-' + o.family + '" aria-hidden="true"></span><a href="oils/' + o.id + '.html">' + mainName + "</a></h3>" +
          '<span class="oil-sub">' + sub + "</span></div>" +
          '<div class="oil-tags">' + tags + "</div>" +
          '<p class="oil-desc">' + (en && oe.desc ? oe.desc : o.desc) + "</p>" +
          (metaRows ? '<dl class="oil-meta">' + metaRows + "</dl>" : "") +
          (cautionText ? '<p class="oil-caution">' + cautionText + "</p>" : "") +
          oilShopHtml(o, en) +
          '<div class="oil-articles"><span class="oa-label">' + (en ? "Featured in these articles" : "紹介されている記事") + "</span>" + artBtns + '<a class="oil-page-link" href="oils/' + o.id + '.html">精油プロフィールページ →</a>' + "</div>";
        card.querySelectorAll("[data-oil-article]").forEach(function (b) {
          b.addEventListener("click", function () { openArticle(b.getAttribute("data-oil-article")); });
        });
        return card;
      }
      function openZukan(oilId) {
        if (oilId) zukanTheme = "all";
        renderZukan(oilId);
        homeView.style.display = "none";
        articleView.classList.remove("open");
        var gv = document.getElementById("guideView");
        if (gv) gv.classList.remove("open");
        zukanView.classList.add("open");
        applyMeta(
          isEn() ? "Essential Oil Encyclopedia | Aroma & Rest Notes" : "精油プロフィール図鑑｜アロマと休息の手帖",
          isEn()
            ? "An encyclopedia of the essential oils featured in this site's lessons and reading articles — searchable by the Japanese syllabary order and by theme, with scent families, Latin names and links to the articles."
            : "学び記事と読み物に登場する精油を集約した図鑑。五十音順とテーマで引けて、香りの系統・学名・紹介記事へのリンクをまとめています。",
          DEFAULT_META.image
        );
        if (oilId) {
          setTimeout(function () {
            var el = document.getElementById("oil-" + oilId);
            if (el) el.scrollIntoView({ behavior: "smooth", block: "center" });
          }, 60);
        } else {
          window.scrollTo({ top: 0 });
        }
      }
      function closeZukan() {
        zukanView.classList.remove("open");
        homeView.style.display = "";
        restoreMeta();
        var target = document.getElementById("zukan");
        if (target) target.scrollIntoView();
      }
      ["zukanBackBtn", "zukanBackBtn2"].forEach(function (id) {
        var el = document.getElementById(id);
        if (el) el.addEventListener("click", closeZukan);
      });
      ["openZukanBtn", "openZukanBtnHero"].forEach(function (zid) {
        var ozb = document.getElementById(zid);
        if (ozb) ozb.addEventListener("click", function () { openZukan(); });
      });
      var navZ = document.getElementById("navZukan");
      if (navZ) navZ.addEventListener("click", function (e) { e.preventDefault(); openZukan(); });

      /* Article -> encyclopedia links (used by both JA and EN article renderers) */
      function zukanLinkHtml(articleId) {
        var oils = oilsForArticle(articleId);
        if (!oils.length) return "";
        var en = isEn();
        var btns = oils.map(function (o) {
          return '<button type="button" class="zl-btn" data-oil-link="' + o.id + '">' + (en ? o.en : o.name) + " →</button>";
        }).join("");
        return '<div class="zukan-link-zone"><h2 class="zl-title">' +
          (en ? "In the encyclopedia — oils in this article" : "図鑑で見る ― この記事に登場する精油") +
          '</h2><div class="zl-btns">' + btns + "</div></div>";
      }
      function bindZukanLinks(scope) {
        if (!scope) return;
        scope.querySelectorAll("[data-oil-link]").forEach(function (b) {
          b.addEventListener("click", function () { openZukan(b.getAttribute("data-oil-link")); });
        });
      }

      /* In-article links to other articles (event delegation, works for JA/EN renderers) */
      document.addEventListener("click", function (e) {
        var t = e.target && e.target.closest ? e.target.closest("[data-article-link]") : null;
        if (t) openArticle(t.getAttribute("data-article-link"));
      });

      /* Per-view SEO / share metadata */
      var DEFAULT_META = {
        title: document.title,
        description: document.querySelector('meta[name="description"]').getAttribute("content"),
        image: "https://tomyree-source.github.io/sites/aroma-notes/assets/hero-aroma.webp"
      };
      function setMeta(selector, attr, value) {
        var el = document.querySelector(selector);
        if (el) el.setAttribute(attr, value);
      }
      function applyMeta(title, description, image) {
        document.title = title;
        setMeta('meta[name="description"]', "content", description);
        setMeta('meta[property="og:title"]', "content", title);
        setMeta('meta[property="og:description"]', "content", description);
        setMeta('meta[property="og:image"]', "content", image);
        setMeta('meta[name="twitter:title"]', "content", title);
        setMeta('meta[name="twitter:description"]', "content", description);
        setMeta('meta[name="twitter:image"]', "content", image);
      }
      function applyArticleMeta(a) {
        var img = a.img;
        if (img && img.indexOf("http") !== 0) img = "https://tomyree-source.github.io/sites/aroma-notes/" + img;
        applyMeta(a.title + "｜アロマと休息の手帖", a.excerpt, img);
      }
      function restoreMeta() {
        applyMeta(DEFAULT_META.title, DEFAULT_META.description, DEFAULT_META.image);
      }

      /* Article view (読み物 + 学習記事 共通) */
      var lastArticleKind = "read";
      function findArticle(id) {
        var found = null;
        ARTICLES.forEach(function (x) { if (x.id === id) { found = x; found._kind = "read"; } });
        if (!found) LEARN_ARTICLES.forEach(function (x) { if (x.id === id) { found = x; found._kind = "learn"; } });
        return found;
      }
      function openArticle(id) {
        var a = findArticle(id);
        if (!a) return;
        lastArticleKind = a._kind || "read";
        var tagLabel = lastArticleKind === "learn" ? pillarName(a.pillar) : catName(a.cat);
        var slotsHtml = '<div class="prod-list">' + (a.products || []).map(function (p) {
          return productCard(p.asin, p.note);
        }).join("") + "</div>";
        var recommendHtml = a.recommend ? '<p style="margin:0 0 14px;color:var(--ink-soft);">' + a.recommend + "</p>" : "";
        articleMount.innerHTML =
          '<div class="article-hero"><img src="' + a.img + '" alt="' + a.alt + '" /></div>' +
          '<article class="post">' +
            '<div class="a-meta"><span class="tag">' + tagLabel + "</span><span>" + a.date + "</span><span>PR：広告を含みます</span></div>" +
            '<h2 class="article-title">' + a.title + "</h2>" +
            '<div class="pr-note"><strong>広告表記（PR）</strong>この記事には広告（アフィリエイトリンク）を含みます。商品リンクはAmazon.co.jpの商品ページへのリンク（tag=cat22202-22）です。実際に使用していない商品の体験談や使用感は掲載していません。価格を表示する場合は調査時点の参考価格です。</div>' +
            a.body +
            '<div class="product-zone">' +
              '<h2 class="pz-title">この記事のテーマに合うおすすめ商品</h2>' +
              '<p class="pz-pr">PR：広告を含みます。価格は調査時点の参考価格で、変動します。最新の価格はAmazon.co.jpの各商品ページでご確認ください。</p>' +
              recommendHtml +
              slotsHtml +
            "</div>" +
            zukanLinkHtml(a.id) +
          "</article>" +
          '<div class="article-nav-foot">' +
            '<button class="back-btn" type="button" data-back>← 一覧に戻る</button>' +
          "</div>";
        var back = articleMount.querySelector("[data-back]");
        back.addEventListener("click", closeArticle);
        bindZukanLinks(articleMount);
        homeView.style.display = "none";
        var gv = document.getElementById("guideView");
        if (gv) gv.classList.remove("open");
        var zv2 = document.getElementById("zukanView");
        if (zv2) zv2.classList.remove("open");
        articleView.classList.add("open");
        applyArticleMeta(a);
        window.scrollTo({ top: 0 });
      }
      function closeArticle() {
        articleView.classList.remove("open");
        homeView.style.display = "";
        restoreMeta();
        var target = document.getElementById(lastArticleKind === "learn" ? "learn" : "articles");
        if (target) target.scrollIntoView();
      }
      document.getElementById("backBtn").addEventListener("click", closeArticle);
      document.getElementById("brandHome").addEventListener("click", function (e) {
        if (articleView.classList.contains("open") || document.getElementById("guideView").classList.contains("open") || document.getElementById("zukanView").classList.contains("open")) {
          e.preventDefault();
          articleView.classList.remove("open");
          document.getElementById("guideView").classList.remove("open");
          document.getElementById("zukanView").classList.remove("open");
          homeView.style.display = "";
          restoreMeta();
          window.scrollTo({ top: 0 });
        }
      });
      document.querySelectorAll("[data-nav]").forEach(function (link) {
        link.addEventListener("click", function () {
          if (articleView.classList.contains("open") || document.getElementById("guideView").classList.contains("open") || document.getElementById("zukanView").classList.contains("open")) {
            articleView.classList.remove("open");
            document.getElementById("guideView").classList.remove("open");
            document.getElementById("zukanView").classList.remove("open");
            homeView.style.display = "";
            restoreMeta();
          }
        });
      });
    

